8	func mergeProjectionTrace(results *SignalResults, p config.Projections) *projectiontrace.Trace {
9		var existingPartitions []projectiontrace.PartitionResolution
10		if results.ProjectionTrace != nil && len(results.ProjectionTrace.Partitions) > 0 {
11			existingPartitions = append([]projectiontrace.PartitionResolution(nil), results.ProjectionTrace.Partitions...)
12		}
13		tr := &projectiontrace.Trace{SchemaVersion: projectiontrace.SchemaVersion}
14		tr.Partitions = existingPartitions
15		for _, score := range p.Scores {
16			sb := projectiontrace.ScoreBreakdown{Name: score.Name}
17			var sum float64
18			for _, input := range score.Inputs {
19				v := projectionInputValue(input, results)
20				contrib := input.Weight * v
21				sum += contrib
22				sb.Inputs = append(sb.Inputs, projectiontrace.ScoreInputPart{
23					Type:         input.Type,
24					Name:         input.Name,
25					KB:           input.KB,
26					Metric:       input.Metric,
27					Weight:       input.Weight,
28					Value:        v,
29					Contribution: contrib,
30				})
31			}
32			sb.Total = sum
33			tr.Scores = append(tr.Scores, sb)
34		}
35		for _, mapping := range p.Mappings {
36			scoreValue, ok := results.ProjectionScores[mapping.Source]
37			if !ok {
38				continue
39			}
40			md := projectiontrace.MappingDecision{
41				MappingName: mapping.Name,
42				SourceScore: mapping.Source,
43				ScoreValue:  scoreValue,
44			}
45			for _, output := range mapping.Outputs {
46				matched := projectionOutputMatches(output, scoreValue)
47				d := projectionBoundaryDistance(output, scoreValue)
48				md.Outputs = append(md.Outputs, projectiontrace.OutputEvalStep{
49					Name:             output.Name,
50					Matched:          matched,
51					BoundaryDistance: d,
52				})
53				if matched && md.SelectedOutput == "" {
54					out := output
55					md.SelectedOutput = out.Name
56					md.Confidence = projectionOutputConfidence(mapping, out, scoreValue)
57					md.BoundaryDistance = d
58				}
59			}
60			tr.Mappings = append(tr.Mappings, md)
61		}
62		return tr
63	}
64

