1	package classification
2	
3	import (
4		"math"
5	
6		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
7	)
8	
9	// applyProjectionMapping records the matched output band(s) for a mapping
10	// according to its method. threshold_bands and the empty default emit only the
11	// first matching band; multi_emit emits every matching band so orthogonal policy
12	// tags can propagate simultaneously.
13	func applyProjectionMapping(
14		mapping config.ProjectionMapping,
15		scoreValue float64,
16		results *SignalResults,
17	) {
18		switch mapping.Method {
19		case config.ProjectionMappingMethodMultiEmit:
20			for _, output := range mapping.Outputs {
21				if projectionOutputMatches(output, scoreValue) {
22					recordProjectionMatch(mapping, output, scoreValue, results)
23				}
24			}
25		default:
26			if output, matched := matchProjectionOutput(mapping, scoreValue); matched {
27				recordProjectionMatch(mapping, output, scoreValue, results)
28			}
29		}
