55		if output.GT != nil && !(scoreValue > *output.GT) {
56			return false
57		}
58		if output.GTE != nil && !(scoreValue >= *output.GTE) {
59			return false
60		}
61		if output.LT != nil && !(scoreValue < *output.LT) {
62			return false
63		}
64		if output.LTE != nil && !(scoreValue <= *output.LTE) {
65			return false
66		}
67		return true
68	}
