70	func projectionOutputConfidence(
71		mapping config.ProjectionMapping,
72		output config.ProjectionMappingOutput,
73		scoreValue float64,
74	) float64 {
75		slope := 12.0
76		if mapping.Calibration != nil && mapping.Calibration.Slope > 0 {
77			slope = mapping.Calibration.Slope
78		}
79	
80		distance := projectionBoundaryDistance(output, scoreValue)
81		return 1.0 / (1.0 + math.Exp(-slope*distance))
