84	func projectionBoundaryDistance(output config.ProjectionMappingOutput, scoreValue float64) float64 {
85		distances := make([]float64, 0, 4)
86		if output.GT != nil {
87			distances = append(distances, math.Abs(scoreValue-*output.GT))
