					}},
					Mappings: []config.ProjectionMapping{{
						Name:   "event_risk_band",
						Source: "event_risk_score",
						Method: "threshold_bands",
						Outputs: []config.ProjectionMappingOutput{
							{Name: "event_risk_high", GTE: float64Ptr(0.8)},
