						Inputs: []config.ProjectionScoreInput{
							{
								Type:        config.SignalTypeStructure,
								Name:        "many_questions",
								Weight:      0.4,
								ValueSource: "raw",
							},
							{
								Type:        config.SignalTypeKeyword,
								Name:        "reasoning_markers",
								Weight:      0.6,
								ValueSource: "confidence",
							},
						},
